"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["463"],{67627(e){e.exports=JSON.parse('{"id":"F120","slug":"capital-gains-tax","name":"Capital Gains and Dividend Tax","subject":"Personal Finance","section":"Personal Finance","topic":"Taxes on investments: capital gains and dividends","level":"Beginner","aliases":["taxes on investments","short term vs long term gains","after tax proceeds","tax loss offset"],"formula":{"latex":"\\\\text{Tax}=r_{cg}\\\\times\\\\max(P-\\\\text{Basis}-\\\\text{Losses},0)+r_{d}\\\\times\\\\text{Dividends}","also":[],"text":"Capital gain = sale proceeds - cost basis; Taxable gain = gain minus any capital losses used against it (not below 0); Tax = capital gains rate (short-term or long-term depending on holding period) x taxable gain + dividend tax rate x dividends"},"symbols":[{"symbol":"P","meaning":"Sale proceeds","unit":"money"},{"symbol":"Basis","meaning":"What you paid, plus eligible costs","unit":"money"},{"symbol":"r_cg","meaning":"Capital gains rate: usually lower if held more than a set period (for example one year)","unit":"percent"},{"symbol":"r_d","meaning":"Tax rate on dividends","unit":"percent"}],"when_to_use":"Use it to estimate the tax cost of selling or of holding income-paying investments. Holding past the long-term threshold often cuts the rate, and losses can offset gains. Rules differ widely by country (some have no capital gains tax, others tax gains as ordinary income), so enter the rates and thresholds from your own tax rules. The rates below are illustrative.","worked_example":{"problem":"You sell shares bought for 8,000 for 15,000, and you also received 1,200 of dividends. You have a 500 capital loss to use. The short-term rate is 32% and the long-term rate is 15%; dividends are taxed at 15%.","inputs":{"basis":8000,"pro":15000,"loss":500,"long":1,"sr":32,"lr":15,"div":1200,"dr":15},"steps":[{"label":"Capital gain = proceeds - basis","working":"15000-8000","value":"7,000.00"},{"label":"Taxable gain after losses","working":"max(7000-500, 0)","value":"6,500.00"},{"label":"Rate applied","working":"0.15 if 1==1 else 0.32","value":"15.0%"},{"label":"Tax on the gain","working":"6500 x 0.15","value":"975.00"},{"label":"Tax on dividends","working":"1200 x 0.15","value":"180.00"},{"label":"Total tax","working":"975+180","value":"1,155.00"},{"label":"Kept from the sale after tax on the gain","working":"15000-975","value":"14,025.00"},{"label":"Tax on the gain if short-term","working":"6500 x 0.32","value":"2,080.00"},{"label":"Saving from the long-term rate","working":"2080-6500 x 0.15","value":"1,105.00"}],"answer":"The gain is 7,000.00, and 6,500.00 is taxable after using the loss. At the 15.0% rate the tax on the gain is 975.00, plus 180.00 on dividends, so 1,155.00 in total. After tax you keep 14,025.00 from the sale. Had the shares been held short-term, the tax on the gain would have been 2,080.00, a difference of 1,105.00."},"calculator":{"available":true,"inputs":[{"id":"basis","label":"Cost basis","unit":"money","type":"number","default":8000,"hint":""},{"id":"pro","label":"Sale proceeds","unit":"money","type":"number","default":15000,"hint":""},{"id":"loss","label":"Capital losses available","unit":"money","type":"number","default":500,"hint":""},{"id":"long","label":"Held long-term? (1 = yes, 0 = no)","unit":"","type":"number","default":1,"hint":""},{"id":"sr","label":"Short-term rate","unit":"%","type":"number","default":32,"hint":""},{"id":"lr","label":"Long-term rate","unit":"%","type":"number","default":15,"hint":""},{"id":"div","label":"Dividends received","unit":"money","type":"number","default":1200,"hint":""},{"id":"dr","label":"Dividend tax rate","unit":"%","type":"number","default":15,"hint":""}],"checks":[{"expr":"long==0 or long==1","message":"Enter 1 for long-term or 0 for short-term."}],"steps":[{"id":"gain","label":"Capital gain = proceeds - basis","expr":"pro-basis","format":"money"},{"id":"taxable","label":"Taxable gain after losses","expr":"max(gain-loss, 0)","format":"money"},{"id":"rate_","label":"Rate applied","expr":"lr if long==1 else sr","format":"pct1"},{"id":"tgain","label":"Tax on the gain","expr":"taxable*rate_","format":"money"},{"id":"tdiv","label":"Tax on dividends","expr":"div*dr","format":"money"},{"id":"total","label":"Total tax","expr":"tgain+tdiv","format":"money"},{"id":"keep","label":"Kept from the sale after tax on the gain","expr":"pro-tgain","format":"money"},{"id":"tshort","label":"Tax on the gain if short-term","expr":"taxable*sr","format":"money"},{"id":"save","label":"Saving from the long-term rate","expr":"tshort-taxable*lr","format":"money"}],"results":["gain","tgain","total","keep"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"gain":7000,"taxable":6500,"rate_":0.15,"tgain":975,"tdiv":180,"total":1155,"keep":14025,"tshort":2080,"save":1105}},"finder":{"finds":"The tax cost of a sale and of dividends","needs":"Basis, proceeds, losses, holding period, rates, dividends"},"related":[{"slug":"income-tax-brackets","name":"Progressive Income Tax: Marginal and Effective Rates"},{"slug":"after-tax-return-tey","name":"After-Tax Return and Tax-Equivalent Yield"},{"slug":"traditional-vs-roth","name":"Traditional vs Roth Account After Tax"}],"related_ids":["F118","F255","F119"],"group":"Personal finance","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Tax</mtext><mo>=</mo><msub><mi>r</mi><mrow><mi>c</mi><mi>g</mi></mrow></msub><mo>\xd7</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>P</mi><mo>\u2212</mo><mtext>Basis</mtext><mo>\u2212</mo><mtext>Losses</mtext><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub><mo>\xd7</mo><mtext>Dividends</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Tax}=r_{cg}\\\\times\\\\max(P-\\\\text{Basis}-\\\\text{Losses},0)+r_{d}\\\\times\\\\text{Dividends}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Tax</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Tax}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><msub><mi>r</mi><mrow><mi>c</mi><mi>g</mi></mrow></msub><mo>\xd7</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>P</mi><mo>\u2212</mo><mtext>Basis</mtext><mo>\u2212</mo><mtext>Losses</mtext><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub><mo>\xd7</mo><mtext>Dividends</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =r_{cg}\\\\times\\\\max(P-\\\\text{Basis}-\\\\text{Losses},0)+r_{d}\\\\times\\\\text{Dividends}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"urr-implicit-tax","name":"Capital Controls: Reserve Requirement Implicit Tax"},"next":{"slug":"capital-market-line","name":"Capital Market Line (CML)"},"lesson":null,"total":522}')}}]);